reference_solution:
def recoverTree(root):
    first = second = prev = None
    st, cur = [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        if prev and prev.val > cur.val:
            if not first:
                first = prev
            second = cur
        prev = cur
        cur = cur.right
    first.val, second.val = second.val, first.val

brute_force_solution:
def recoverTree(root):
    nodes, st, cur = [], [], root
    while st or cur:
        while cur:
            st.append(cur)
            cur = cur.left
        cur = st.pop()
        nodes.append(cur)
        cur = cur.right
    vals = sorted(n.val for n in nodes)
    for n, v in zip(nodes, vals):
        n.val = v

